events.command:
KEY=$(cat $GALAXY_API_KEY_FILE)
curl -s "https://usegalaxy.org/api/histories/bbd44e69cb8906b5f1a5dc97941f980a/contents" \
  -H "x-api-key: $KEY" | python3 -c "
import sys, json
try:
    data = json.load(sys.stdin)
    if isinstance(data, list):
        for d in data:
            print(f\"{d['id']}: {d['name']} ({d.get('file_size', '?')} bytes) [{d['state']}]\")
        print(f'Total: {len(data)} datasets')
    else:
        print(json.dumps(data, indent=2)[:2000])
except Exception as e:
    print(f'Error: {e}')
"

